import json,hashlib
from pathlib import Path
root=Path.home()/'dojo-data/laptop';out={'rows':[],'screens':[],'pilots':[],'auxiliary':[],'manifests':{},'admissions':{},'recipes':{},'deployments':{}}
for d in root.glob('r2f-panel-*'):
 if not d.is_dir():continue
 for p in d.glob('*_episodes.jsonl'):
  out['rows'].extend(dict(json.loads(l),run_dir=d.name) for l in p.read_text().splitlines())
for bank,data in [('old',root),('coverage18',root/'coverage18')]:
 for d in data.glob('r2f-production-*'):
  if not d.is_dir():continue
  for p in d.glob('*_episodes.jsonl'):
   out['screens'].extend({'bank':bank,'run_dir':str(d.relative_to(root)),'row':json.loads(l)} for l in p.read_text().splitlines())
for p in (root/'round2f').glob('*/row.json'):
 out['pilots'].append({'path':str(p.relative_to(root)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'row':json.loads(p.read_text())})
for p in (root/'coverage18/round2f').glob('*/row.json'):
 out['auxiliary'].append({'path':str(p.relative_to(root)),'row':json.loads(p.read_text())})
for p in root.glob('round2f-*.json'):out['manifests'][p.name]=json.loads(p.read_text())
for p in (root/'logs').glob('r2f-*.admission'):out['admissions'][p.name]=p.read_text()
for p in sorted(root.glob('round2f-*.py'))+[root/'job-f.sh']:
 out['recipes'][p.name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'source':p.read_text()}
for d in [Path.home()/'controlr-laptop',Path.home()/'controlr-laptop/frozen-round2f']:
 out['deployments'][str(d)]={'stamp':(d/'.deployed_commit').read_text().strip(),'metadata':json.loads((d/'.deployed.json').read_text()),'hashes':{f:hashlib.sha256((d/f).read_bytes()).hexdigest() for f in ['dojo/skills/headset.py','dojo/skills/library.py','dojo/skills/skills.py','dojo/skills/g3.py','dojo/runtime/policy.py','dojo/skills/motion.py','dojo/skills/grasps.py','dojo/skills/kinematics.py']}}
print(json.dumps(out))

